sys_script_include.script:
var FeedbackUtils = Class.create();
FeedbackUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	submit: function() {
		var sysId = this.getParameter('sysparm_sys_id');
		var rating = this.getParameter('sysparm_rating');
		var comments = this.getParameter('sysparm_comments');
		var eventId = this.getParameter('sysparm_event_id');
		var userId = this.getParameter('sysparm_user_id');

		var gr = new GlideRecord('x_1790139_event_ma_feedback');
		if (gr.get(sysId)) {
			gr.setValue('x_rating', rating);
			gr.setValue('x_comments', comments);
			gr.setValue('x_event', eventId);
			gr.setValue('x_attendee_id', userId);
			gr.update(); 
		}

		return "success";
	},
	type: 'FeedbackUtils'
});
